		switch content[i] {
		case '\'', '"':
			quote := content[i]
			backslashEscapes := quote == '\'' && postgresEscapeStringPrefix(content, i)
			i++ // preserve the opening quote
			for i < len(content) {
				if backslashEscapes && content[i] == '\\' && i+1 < len(content) {
					masked[i] = ' '
					if content[i+1] != '\n' && content[i+1] != '\r' {
						masked[i+1] = ' '
					}
					i += 2
					continue
				}
				if content[i] == quote {
					if i+1 < len(content) && content[i+1] == quote {
						masked[i] = ' '
						masked[i+1] = ' '
						i += 2
						continue
					}
					i++ // preserve the closing quote
					break
				}
				if content[i] != '\n' && content[i] != '\r' {
					masked[i] = ' '
				}
				i++
			}
		case '$':
			tag, ok := dollarQuoteTag(content, i)
			if !ok {
				i++
				continue
			}
			bodyStart := i + len(tag)
			closeRel := strings.Index(content[bodyStart:], tag)
			if closeRel < 0 {
				i = bodyStart
				continue
			}
